Here is a clean Python implementation of the Template Method pattern for sorting. The template defines the overall sorting workflow and the primitive operations `compare` and `swap` are supplied by the concrete algorithms.

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    """Template Method skeleton"""
    def __init__(self, data: List[Any]):
        self.data = data.copy()

    def sort(self) -> List[Any]:
        """Template method - final, not overridden"""
        self._sort_impl()
        return self.data

    @abstractmethod
    def _sort_impl(self) -> None:
        """Concrete algorithm steps - implemented by subclasses"""
        pass

    def compare(self, a: Any, b: Any) -> int:
        # Default comparison, can be overridden for custom ordering
        return (a > b) - (a < b)

    def swap(self, i: int, j: int) -> None:
        self.data[i], self.data[j] = self.data[j], self.data[i]


class BubbleSort(SortAlgorithm):
    def _sort_impl(self) -> None:
        n = len(self.data)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]) > 0:
                    self.swap(j, j + 1)
                    swapped = True
            if not swapped:
                break


class SelectionSort(SortAlgorithm):
    def _sort_impl(self) -> None:
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[j], self.data[min_idx]) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    nums = [64, 25, 12, 22, 11]
    strings = ["banana", "apple", "cherry"]

    print("BubbleSort ints:", BubbleSort(nums).sort())
    print("SelectionSort ints:", SelectionSort(nums).sort())
    print("BubbleSort strings:", BubbleSort(strings).sort())
    print("SelectionSort strings:", SelectionSort(strings).sort())
```

The `SortAlgorithm.sort()` is the template method. `BubbleSort` and `SelectionSort` provide their own `_sort_impl` with the specific algorithm steps, while `compare` and `swap` are reusable primitive operations.
